    private static readonly Dictionary<string, string> German = new()
    {
        [ServerHelpTitle] = "Wähle deinen Server",
        [ServerHelpBody] = "In Discord Desktop:\n1. Öffne Benutzereinstellungen > Erweitert > Entwicklermodus.\n2. Klicke mit der rechten Maustaste auf das Serversymbol und wähle Server-ID kopieren.\n3. Füge die ID im Editor ein.\n\nDu kannst auch den Link eines Textkanals kopieren und einfügen. Einladungslinks enthalten keine Server-ID. Du musst dem Server bereits angehören. Tokens oder Zugangsdaten werden nicht benötigt.",
        [HelpTitle] = "Theme Studio · Hilfe",
        [HelpBody] = "Erstelle ein neutrales Fluent-Dark-Thema oder wähle unter Community ein Design. Du kannst eine heruntergeladene .theme.css importieren. Die Kompatibilitätsprüfung zeigt unterstützte Variablen und Ressourcen. Nicht unterstütztes CSS wird vor Änderungen abgewiesen; beliebige Netzwerkressourcen werden nicht geladen. Zenit Gold stammt von JACKPOT71; die Serveranpassung bewahrt Originalbilder und Design.\n\nWähle einen Zielserver. Stil und Bilder ändern nur die Vorschau. Anderer Server und Direktnachrichten zeigen unverändertes Discord. Abgetrennte Einstellungen und Popouts bleiben unverändert. Erst Fortfahren und anwenden bestätigt die Änderung und den Discord-Neustart. Zurück zur Vorschau oder Esc bricht ab. Fehlendes Vencord wird nur mit ausdrücklicher Zustimmung eingerichtet.\n\nÖffnen, Speichern und Thema teilen verwenden portable .dtheme-Dateien mit ausgewählten Bildern, Schriften, Lizenzen und gegebenenfalls dem ursprünglichen CSS. Du kannst mehrere Dateien speichern; nur ein persönliches Thema ist gleichzeitig aktiv. Wiederherstellung bietet Deaktivieren und Zurücksetzen. Andere Themen, Plugins und QuickCSS bleiben erhalten.\n\nNur Windows x64, Discord Stable Desktop und das Standardprofil von Vencord werden automatisch unterstützt. Vencord ist inoffiziell; Client-Modifikationen haben Auswirkungen auf Discord-Nutzungsbedingungen und Kontorisiken. Dieses Werkzeug ist nicht mit Discord verbunden.\n\nEigene statische TTF/OTF-Schriften brauchen Einbettungs- und Weitergaberechte sowie den Lizenztext. PNG/JPEG-Bilder: höchstens 8 MiB, 4096 px je Seite und 16 Millionen Pixel. Konfigurationen: höchstens 24 MiB. CSS-Import: höchstens 2 MiB. Weitere Grenzen stehen in der Kompatibilitätsdokumentation. Themenvorschläge werden über eine GitHub-Vorlage oder ein konfiguriertes Discord-Ziel geprüft.",
        [WebViewMissing] = "Theme Studio benötigt Microsoft Edge WebView2 Runtime. Installiere sie von Microsofts offizieller WebView2-Seite und öffne die Anwendung erneut. Deine .dtheme-Dateien bleiben erhalten.\n\nhttps://developer.microsoft.com/microsoft-edge/webview2/",
        [PreviewWebViewMissing] = "Die lokale Vorschau benötigt Microsoft Edge WebView2 Runtime.\nInstalliere sie von Microsofts offizieller Seite und öffne die Anwendung erneut.\nDeine Konfiguration kann weiterhin gespeichert und geteilt werden.",
