        ["The stylesheet is not valid UTF-8 or contains a damaged embedded resource."] = "Das Stylesheet ist kein gültiges UTF-8 oder enthält eine beschädigte eingebettete Ressource.",
        ["Server adaptation: document roots map to the selected server pane. Fixed layers are clipped to it; detached settings and popouts keep their normal appearance."] = "Serveranpassung: Dokumentwurzeln werden dem ausgewählten Serverbereich zugeordnet. Feste Ebenen werden darauf begrenzt; abgetrennte Einstellungen und Popouts behalten ihr normales Aussehen.",
        ["External or active CSS resources are unsupported. Embed licensed images/fonts locally; no resource was downloaded."] = "Externe oder aktive CSS-Ressourcen werden nicht unterstützt. Bette lizenzierte Bilder und Schriften lokal ein. Es wurde keine Ressource heruntergeladen.",
        ["Only embedded PNG, JPEG, WebP, TTF and WOFF2 resources are supported. Relative paths, SVG and network URLs are blocked."] = "Nur eingebettete PNG-, JPEG-, WebP-, TTF- und WOFF2-Ressourcen werden unterstützt. Relative Pfade, SVG und Netzwerkadressen werden blockiert.",
        ["Embedded resource is damaged or oversized."] = "Eine eingebettete Ressource ist beschädigt oder zu groß.",
        ["Embedded resource signature does not match its declared format."] = "Die Signatur einer eingebetteten Ressource passt nicht zu ihrem angegebenen Format.",
        ["Unsupported document-root selector. Keep html/body/:root/#app-mount at the beginning of a selector, without CSS nesting."] = "Nicht unterstützter Dokumentwurzel-Selektor. html, body, :root und #app-mount müssen am Anfang stehen, ohne CSS-Verschachtelung.",
        ["Fixed backgrounds and decorations are contained inside the selected server pane."] = "Feste Hintergründe und Dekorationen werden auf den ausgewählten Serverbereich begrenzt.",
        ["A stylesheet-level @import needs a reviewed offline adapter. Download a self-contained CSS design instead. No resource was fetched."] = "Ein @import auf Stylesheet-Ebene benötigt eine geprüfte Offline-Anpassung. Lade stattdessen ein eigenständiges CSS-Design herunter. Es wurde keine Ressource abgerufen.",
        ["The stylesheet exposes too many editable variables (maximum 128)."] = "Das Stylesheet enthält zu viele bearbeitbare Variablen (höchstens 128).",
        ["Unsupported imported variable edit. Use the color or numeric controls shown in the compatibility review."] = "Nicht unterstützte Änderung einer importierten Variablen. Verwende die in der Kompatibilitätsprüfung angezeigten Farb- oder Zahlenfelder.",
        ["Unsupported or malformed CSS syntax. Use a self-contained stylesheet without nesting or escaped identifiers."] = "Nicht unterstützte oder fehlerhafte CSS-Syntax. Verwende ein eigenständiges Stylesheet ohne Verschachtelung oder maskierte Bezeichner."
        ,["Unsupported stylesheet rule: {0}. @media, @supports, @container and named animations are supported; global registrations and nested CSS need a reviewed adapter."] = "Nicht unterstützte Stylesheet-Regel: {0}. @media, @supports, @container und benannte Animationen werden unterstützt; globale Registrierungen und verschachteltes CSS benötigen eine geprüfte Anpassung."
        ,["A bundled interface resource is missing."] = "Eine enthaltene Oberflächenressource fehlt."
        ,["Bundled theme resource is missing."] = "Eine enthaltene Themenressource fehlt."
        ,["Invalid theme catalog."] = "Ungültiger Themenkatalog."
        ,["The selected location contains a linked folder or file. Use a regular local profile."] = "Der ausgewählte Speicherort enthält einen verknüpften Ordner oder eine verknüpfte Datei. Verwende ein reguläres lokales Profil."
        ,["Unknown artwork area."] = "Unbekannter Bildbereich."
        ,["Unknown preset."] = "Unbekannte Vorlage."
        ,["Unsupported theme catalog."] = "Nicht unterstützter Themenkatalog."
        ,["Export original CSS"] = "Ursprüngliches CSS exportieren"
        ,["Embedded images must have valid dimensions up to 4096 × 4096 and 16 million pixels."] = "Eingebettete Bilder benötigen gültige Abmessungen mit höchstens 4096 × 4096 und 16 Millionen Pixeln."
        ,["This CSS can remove server containment. all resets, unbounded containment and indirect display values require a reviewed adapter."] = "Dieses CSS kann die Serverbegrenzung aufheben. all-Zurücksetzungen, unbegrenzte Darstellung und indirekte display-Werte benötigen eine geprüfte Anpassung."
        ,["Document-root layout changes cannot preserve the server pane bounds. Move layout rules to a descendant selector or use a reviewed adapter."] = "Layoutänderungen an der Dokumentwurzel können die Grenzen des Serverbereichs nicht bewahren. Verwende für Layoutregeln einen untergeordneten Selektor oder eine geprüfte Anpassung."
        ,["bytes · embedded"] = "Byte · eingebettet"
        ,["reviewed bundled font"] = "geprüfte enthaltene Schrift"
        ,["Embedded images exceed the combined 32 million pixel preview budget. Use fewer or smaller images."] = "Eingebettete Bilder überschreiten zusammen das Vorschaulimit von 32 Millionen Pixeln. Verwende weniger oder kleinere Bilder."
    };
}
